using System;
using System.Linq;
using System.Collections.Generic;
using Newtonsoft.Json.Linq;
using UnityEngine;
namespace LastRail.Battle {
 // Presentation only; callbacks forward input to the QA controller's existing native commands.
 public sealed class BOrdinaryLiveQaView:MonoBehaviour {
  Func<JObject> observe;Func<string> outcome;Func<bool> paused;Func<int> hp;Action start,pause,restart,move,intercept;
  readonly Dictionary<string,GameObject> groups=new Dictionary<string,GameObject>(),markers=new Dictionary<string,GameObject>();
  readonly List<Material> materials=new List<Material>();GameObject root;Camera camera;TextMesh caption;JObject snapshot;string error;
  public bool Demonstration {get;private set;}=true;
  static Vector3 Point(JToken p)=>new Vector3((float)p[0]/1000,(float)p[1]/1000,(float)p[2]/1000);
  public void Bind(BOrdinaryGeometryBinding geometry,Func<JObject> state,Func<string> status,Func<bool> isPaused,Func<int> currentHp,Action begin,Action toggle,Action again,Action walk,Action shield){Unbind();observe=state;outcome=status;paused=isPaused;hp=currentHp;start=begin;pause=toggle;restart=again;move=walk;intercept=shield;root=new GameObject("live_native_QA_presentation");root.transform.SetParent(transform);foreach(string name in new[]{"body","roof","paths","actors","projectiles","labels"}){var o=new GameObject("independent_"+name);o.transform.SetParent(root.transform);groups.Add(name,o);}var asset=geometry.Definition.Capture();foreach(var row in geometry.Capture()["instances"]){int slot=(int)row["slot"];foreach(string group in new[]{"body","roof"}){var a=Point(geometry.WorldPoint(slot,(JArray)asset[group+"MinMm"]));var b=Point(geometry.WorldPoint(slot,(JArray)asset[group+"MaxMm"]));var o=Cube(group+slot,group,(a+b)*.5f,group=="body"?new Color(.12f,.15f,.2f):new Color(.3f,.36f,.44f));o.transform.localScale=new Vector3(Math.Abs(a.x-b.x),Math.Max(.03f,Math.Abs(a.y-b.y)),Math.Abs(a.z-b.z));}foreach(string side in new[]{"left","right"})foreach(string path in new[]{"approachMm","climbMm"}){var o=new GameObject(side+path);o.transform.SetParent(groups["paths"].transform);var line=o.AddComponent<LineRenderer>();var points=asset[side][path].Select(p=>Point(geometry.WorldPoint(slot,(JArray)p))).ToArray();line.positionCount=points.Length;line.SetPositions(points);line.startWidth=line.endWidth=.1f;line.sharedMaterial=ColorMaterial(side=="left"?Color.cyan:Color.magenta);}}var cam=new GameObject("live_QA_camera");cam.transform.SetParent(root.transform);camera=cam.AddComponent<Camera>();camera.orthographic=true;camera.orthographicSize=22;camera.transform.position=new Vector3(10,32,-32);camera.transform.LookAt(new Vector3(0,1,0));camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=new Color(.04f,.05f,.08f);camera.aspect=1280f/720;caption=new GameObject("native_status_world_labels").AddComponent<TextMesh>();caption.transform.SetParent(groups["labels"].transform);caption.font=UnityEngine.Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");caption.GetComponent<Renderer>().sharedMaterial=caption.font.material;caption.anchor=TextAnchor.UpperLeft;caption.fontSize=48;caption.characterSize=.25f;caption.transform.position=camera.ViewportToWorldPoint(new Vector3(.04f,.74f,20));caption.transform.rotation=camera.transform.rotation;}
  Material ColorMaterial(Color color){var m=new Material(Shader.Find("Unlit/Color")){color=color};materials.Add(m);return m;}
  GameObject Cube(string id,string group,Vector3 point,Color color){var o=GameObject.CreatePrimitive(PrimitiveType.Cube);Destroy(o.GetComponent<Collider>());o.name=id;o.transform.SetParent(groups[group].transform);o.transform.position=point;o.transform.localScale=Vector3.one*.5f;o.GetComponent<Renderer>().sharedMaterial=ColorMaterial(color);return o;}
  void Marker(string id,string group,Vector3 point,Color color){if(!markers.TryGetValue(id,out var o)){o=Cube(id,group,point,color);markers.Add(id,o);}o.SetActive(true);o.transform.position=point;}
  void LateUpdate(){if(observe==null)return;snapshot=observe();if(snapshot==null){caption.text="LOCAL TEST MODEL / READY";return;}caption.text="LOCAL TEST MODEL / LIVE NATIVE\n"+outcome()+"  tick "+snapshot["spatialSource"]["tick"]+"  HP "+hp()+"\n"+string.Join(" / ",snapshot["spatialSource"]["positions"].GroupBy(p=>(string)p["phase"]).Select(g=>g.Key+":"+g.Count()))+"\n"+string.Join(" / ",snapshot["gunnerIntercept"]["projectiles"].GroupBy(p=>(string)p["terminal"]).Select(g=>g.Key+":"+g.Count()));foreach(var o in markers.Values)o.SetActive(false);var space=snapshot["spatialSource"];foreach(var op in space["operators"])Marker((string)op["id"],"actors",Point(op["positionMm"])+Vector3.up*.35f,Color.green);foreach(var e in space["positions"].Where(e=>(string)e["phase"]!="Dead"))Marker((string)e["id"],"actors",Point(e["positionMm"])+Vector3.up*.35f,Color.red);long tick=(long)space["tick"];foreach(var s in snapshot["gunnerIntercept"]["projectiles"].Where(s=>(string)s["terminal"]=="FLYING")){float t=(float)(tick-(long)s["launchTick"])/((long)s["contactTick"]-(long)s["launchTick"]);Marker((string)s["id"],"projectiles",Vector3.Lerp(Point(s["sourcePointMm"]),Point(s["targetPointMm"]),Mathf.Clamp01(t)),new Color(1,.6f,.1f));}}
  void Invoke(Action action){try{action?.Invoke();error=null;}catch(Exception e){error=e.Message;Debug.LogException(e,this);}}
  void OnGUI(){if(observe==null)return;GUILayout.BeginArea(new Rect(18,18,620,250),GUI.skin.box);GUILayout.Label("LOCAL TEST MODEL — Kyle test profile / operating support unavailable");GUILayout.BeginHorizontal();if(GUILayout.Button("Start"))Invoke(start);if(GUILayout.Button(paused()?"Resume":"Pause"))Invoke(pause);if(GUILayout.Button("New QA run"))Invoke(restart);if(GUILayout.Button("Move Kyle 6m"))Invoke(move);if(GUILayout.Button("Intercept"))Invoke(intercept);GUILayout.EndHorizontal();Demonstration=GUILayout.Toggle(Demonstration,"Automatic QA sequence: intercept → move → native basic attacks");groups["labels"].SetActive(GUILayout.Toggle(groups["labels"].activeSelf,"Show native status labels"));if(groups["labels"].activeSelf){GUILayout.Label("State: "+outcome());if(snapshot!=null){var s=snapshot["spatialSource"];GUILayout.Label("Native tick "+s["tick"]+" / revision "+s["revision"]);GUILayout.Label("Kyle HP "+hp());GUILayout.Label(string.Join(" / ",s["positions"].GroupBy(p=>(string)p["phase"]).Select(g=>g.Key+": "+g.Count())));GUILayout.Label("Projectiles: "+snapshot["gunnerIntercept"]["projectiles"].Count());}}GUILayout.BeginHorizontal();foreach(var pair in groups.Where(p=>p.Key!="labels"))pair.Value.SetActive(GUILayout.Toggle(pair.Value.activeSelf,pair.Key));GUILayout.EndHorizontal();if(error!=null)GUILayout.Label(error);GUILayout.EndArea();}
  public void Unbind(){observe=null;outcome=null;paused=null;hp=null;start=pause=restart=move=intercept=null;snapshot=null;if(root!=null)Destroy(root);root=null;groups.Clear();markers.Clear();foreach(var m in materials)if(m!=null)Destroy(m);materials.Clear();}
  void OnDestroy(){Unbind();}
 }
}
